import { useEffect, useState } from "react";
import { useNavigate } from "react-router-dom";
import { useAuthState } from "react-firebase-hooks/auth";
import { auth, db } from "../firebase"; // Ensure correct path
import { collection, query, where, getDocs } from "firebase/firestore";
import Chart from "chart.js/auto"; // ✅ Fix: Import Chart properly
import classnames from "classnames";
import { Line, Bar } from "react-chartjs-2";
import {
  Card,
  CardHeader,
  CardBody,
  NavItem,
  NavLink,
  Nav,
  Progress,
  Table,
  Container,
  Row,
  Col,
} from "reactstrap"; // ✅ Fix: Removed unused Button import

import {
  chartOptions,
  parseOptions,
  chartExample1,
  chartExample2,
} from "variables/charts.js";

import Header from "components/Headers/Header.js";

const Index = () => {
  const [activeNav, setActiveNav] = useState(1);
  const [chartExample1Data, setChartExample1Data] = useState("data1");
  const [carbonLogs, setCarbonLogs] = useState([]);
  const [user] = useAuthState(auth);
  const navigate = useNavigate();

  // Redirect if not logged in
  useEffect(() => {
    if (!user) {
      navigate("/auth/login");
    }
  }, [user, navigate]);

  // Fetch user-specific carbon logs
  useEffect(() => {
    if (user) {
      const fetchCarbonLogs = async () => {
        const q = query(collection(db, "carbon_logs"), where("userId", "==", user.uid));
        const querySnapshot = await getDocs(q);
        setCarbonLogs(querySnapshot.docs.map(doc => ({ id: doc.id, ...doc.data() })));
      };

      fetchCarbonLogs();
    }
  }, [user]);

  // ✅ Fix: Ensure Chart.js options are applied
  if (typeof window !== "undefined" && window.Chart) {
    parseOptions(Chart, chartOptions());
  }

  const toggleNavs = (e, index) => {
    e.preventDefault();
    setActiveNav(index);
    setChartExample1Data("data" + index);
  };

  return (
    <>
      <Header />
      {/* Page content */}
      <Container className="mt--7" fluid>
        <Row>
          <Col className="mb-5 mb-xl-0" xl="8">
            <Card className="bg-gradient-default shadow">
              <CardHeader className="bg-transparent">
                <Row className="align-items-center">
                  <div className="col">
                    <h6 className="text-uppercase text-light ls-1 mb-1">Overview</h6>
                    <h2 className="text-white mb-0">Carbon Emissions Over Time</h2>
                  </div>
                  <div className="col">
                    <Nav className="justify-content-end" pills>
                      <NavItem>
                        <NavLink
                          className={classnames("py-2 px-3", { active: activeNav === 1 })}
                          href="#"
                          onClick={(e) => toggleNavs(e, 1)}
                        >
                          <span className="d-none d-md-block">Month</span>
                          <span className="d-md-none">M</span>
                        </NavLink>
                      </NavItem>
                      <NavItem>
                        <NavLink
                          className={classnames("py-2 px-3", { active: activeNav === 2 })}
                          href="#"
                          onClick={(e) => toggleNavs(e, 2)}
                        >
                          <span className="d-none d-md-block">Week</span>
                          <span className="d-md-none">W</span>
                        </NavLink>
                      </NavItem>
                    </Nav>
                  </div>
                </Row>
              </CardHeader>
              <CardBody>
                <div className="chart">
                  <Line data={chartExample1[chartExample1Data]} options={chartExample1.options} />
                </div>
              </CardBody>
            </Card>
          </Col>
          <Col xl="4">
            <Card className="shadow">
              <CardHeader className="bg-transparent">
                <h6 className="text-uppercase text-muted ls-1 mb-1">Performance</h6>
                <h2 className="mb-0">Emission Sources Breakdown</h2>
              </CardHeader>
              <CardBody>
                <div className="chart">
                  <Bar data={chartExample2.data} options={chartExample2.options} />
                </div>
              </CardBody>
            </Card>
          </Col>
        </Row>

        {/* Activity Log Table */}
        <Row className="mt-5">
          <Col xl="8">
            <Card className="shadow">
              <CardHeader className="border-0">
                <h3 className="mb-0">Activity Log</h3>
              </CardHeader>
              <Table className="align-items-center table-flush" responsive>
                <thead className="thead-light">
                  <tr>
                    <th scope="col">Date</th>
                    <th scope="col">Category</th>
                    <th scope="col">Value</th>
                    <th scope="col">CO₂ Emission (kg)</th>
                  </tr>
                </thead>
                <tbody>
                  {carbonLogs.length > 0 ? (
                    carbonLogs.map((log) => (
                      <tr key={log.id}>
                        <td>{log.date}</td>
                        <td>{log.category}</td>
                        <td>{log.value} {log.unit}</td>
                        <td>{log.carbonEmission.toFixed(2)}</td>
                      </tr>
                    ))
                  ) : (
                    <tr>
                      <td colSpan="4" className="text-center">No data available.</td>
                    </tr>
                  )}
                </tbody>
              </Table>
            </Card>
          </Col>

          {/* Credit Transactions Table */}
          <Col xl="4">
            <Card className="shadow">
              <CardHeader className="border-0">
                <h3 className="mb-0">Credit Transactions</h3>
              </CardHeader>
              <Table className="align-items-center table-flush" responsive>
                <thead className="thead-light">
                  <tr>
                    <th scope="col">Activity Type</th>
                    <th scope="col">Credits Earned</th>
                    <th scope="col">Progress</th>
                  </tr>
                </thead>
                <tbody>
                  {/* Placeholder for transactions */}
                  <tr>
                    <td>Carpooling</td>
                    <td>50</td>
                    <td>
                      <Progress max="100" value="50" barClassName="bg-gradient-success" />
                    </td>
                  </tr>
                  <tr>
                    <td>Solar Energy Use</td>
